function ch(right,wrong){const w=[];wrong.forEach(x=>{x=String(x);if(x!==String(right)&&!w.includes(x))w.push(x);});
 const o=shuffle([String(right),...w.slice(0,3)].map((s,i)=>({s,i})));return {opts:o.map(x=>x.s),ans:o.findIndex(x=>x.i===0)};}
/* numeric choice: right + typical mistakes, padded with neighbours */
function chN(right,wrong){const w=[];wrong.forEach(x=>{if(Number.isFinite(x)&&x>=0&&x!==right&&!w.includes(x))w.push(x);});
 let d=1;while(w.length<3){[right+d,right*2,right-d].forEach(x=>{if(x>0&&x!==right&&!w.includes(x)&&w.length<3)w.push(x);});d++;}
 return ch(N(right),w.slice(0,3).map(N));}
/* combinatorics */
const fact=n=>{let r=1;for(let i=2;i<=n;i++)r*=i;return r;};
const A=(n,k)=>{let r=1;for(let i=0;i<k;i++)r*=n-i;return r;};
const C=(n,k)=>{if(k<0||k>n)return 0;k=Math.min(k,n-k);let r=1;for(let i=1;i<=k;i++)r=r*(n-k+i)/i;return Math.round(r);};
const prodS=(n,k)=>range(0,k-1).map(i=>n-i).join(' · ');
function perms(a){if(a.length<=1)return [a.slice()];const r=[];a.forEach((x,i)=>{perms(a.slice(0,i).concat(a.slice(i+1))).forEach(p=>r.push([x,...p]));});return r;}
function combs(a,k){if(k===0)return [[]];if(a.length<k)return [];const [h,...t]=a;return combs(t,k-1).map(c=>[h,...c]).concat(combs(t,k));}
function distinctPerms(w){const s=new Set();perms(w.split('')).forEach(p=>s.add(p.join('')));return s.size;}
const NAMES=['Аня','Боря','Вика','Гоша','Даша','Егор','Женя','Зоя','Илья','Катя','Лёва','Мила'];
/* theory helpers */
const CC=(n,k,L)=>`${L||'C'}<span style="display:inline-flex;flex-direction:column;vertical-align:middle;font-size:0.68em;line-height:1.05;margin-left:1px"><span>${k}</span><span>${n}</span></span>`;
