const EX=(title,task,steps,ans)=>`<div class="box ex"><b>${title}</b>${task}${steps.map((s,i)=>`<div style="margin:5px 0"><b>Шаг ${i+1}.</b> ${s}</div>`).join('')}${ans?`<div style="margin-top:4px">✅ <b>${ans}</b></div>`:''}</div>`;
