function tbl(rows){return '<div style="overflow-x:auto;margin:8px 0"><table style="border-collapse:collapse;margin:0 auto;font-size:15px">'+rows.map((r,i)=>'<tr>'+r.map((c,j)=>{const th=i===0||j===0;return `<${th?'th':'td'} style="${th?TH:TD}">${c}</${th?'th':'td'}>`;}).join('')+'</tr>').join('')+'</table></div>';}

/* ---------- SVG: Pascal triangle ---------- */
function pascSVG(rows,hl){const W=330,sp=Math.min(38,(W-10)/(rows+1)),rh=Math.min(30,sp*0.85),fs=sp<30?11:13;const Hh=rh*(rows+1)+10;
 let s=`<svg viewBox="0 0 ${W} ${Hh}" width="${W}" role="img" aria-label="Треугольник Паскаля" style="font-family:system-ui,sans-serif">`;
 const P=(n,k)=>[W/2+(k-n/2)*sp,rh*n+rh/2+5];
 for(let n=0;n<=rows;n++)for(let k=0;k<=n;k++){const [x,y]=P(n,k);let fill='var(--card)',st='var(--line)',sw=1;
  if(hl){if(n===hl.n&&k===hl.k){fill='var(--hl)';st='var(--accent-ink)';sw=2;}else if(n===hl.n-1&&(k===hl.k||k===hl.k-1)){fill='var(--accent-soft)';st='var(--accent)';sw=2;}}
  s+=`<rect x="${x-sp/2+1.5}" y="${y-rh/2+1}" width="${sp-3}" height="${rh-2}" rx="6" fill="${fill}" ${fill==='var(--hl)'?'fill-opacity="0.55"':''} stroke="${st}" stroke-width="${sw}"/><text x="${x}" y="${y+fs*0.36}" text-anchor="middle" font-size="${fs}" fill="var(--ink)" font-weight="${hl&&n===hl.n&&k===hl.k?700:400}">${C(n,k)}</text>`;}
 return s+'</svg>';}
/* ---------- SVG: grid paths ---------- */
function gridSVG(m,n,block){const cell=Math.min(40,Math.floor(260/Math.max(m,n)));const W=m*cell+60,Hh=n*cell+40;const X=i=>30+i*cell,Y=j=>Hh-20-j*cell;
 let s=`<svg viewBox="0 0 ${W} ${Hh}" width="${W}" role="img" aria-label="Сетка" style="font-family:system-ui,sans-serif">`;
 for(let i=0;i<=m;i++)s+=`<line x1="${X(i)}" y1="${Y(0)}" x2="${X(i)}" y2="${Y(n)}" stroke="var(--fig)" stroke-width="1.3"/>`;
 for(let j=0;j<=n;j++)s+=`<line x1="${X(0)}" y1="${Y(j)}" x2="${X(m)}" y2="${Y(j)}" stroke="var(--fig)" stroke-width="1.3"/>`;
 if(block){s+=`<circle cx="${X(block[0])}" cy="${Y(block[1])}" r="7" fill="var(--bad)" fill-opacity="0.8"/><text x="${X(block[0])+9}" y="${Y(block[1])-7}" font-size="12" fill="var(--ink)">лава</text>`;}
 s+=`<circle cx="${X(0)}" cy="${Y(0)}" r="5" fill="var(--accent-ink)"/><text x="${X(0)-14}" y="${Y(0)+16}" font-size="14" font-weight="700" fill="var(--accent-ink)">A</text>`;
 s+=`<circle cx="${X(m)}" cy="${Y(n)}" r="5" fill="var(--accent-ink)"/><text x="${X(m)+6}" y="${Y(n)-6}" font-size="14" font-weight="700" fill="var(--accent-ink)">B</text>`;
 return s+'</svg>';}
function gridPaths(m,n,block){const d=[];for(let i=0;i<=m;i++){d.push([]);for(let j=0;j<=n;j++){if(block&&i===block[0]&&j===block[1]){d[i][j]=0;continue;}d[i][j]=(i===0&&j===0)?1:((i>0?d[i-1][j]:0)+(j>0?d[i][j-1]:0));}}return d[m][n];}

